{"source":"def investigate(context, acquire):
    actions = context.get('actions')
    if actions is None:
        actions = []
    sqlite = acquire('sqlite')
    connection = sqlite.connect(':memory:')
    cursor = connection.cursor()
    cursor.execute('CREATE TABLE t (id INTEGER PRIMARY KEY AUTOINCREMENT)')
    for action in actions:
        operation = action.get('op')
        if operation == 'put':
            cursor.execute('INSERT INTO t (id) VALUES (?)', (action.get('id'),))
        elif operation == 'delete':
            cursor.execute('DELETE FROM t WHERE id = ?', (action.get('id'),))
        elif operation == 'begin':
            cursor.execute('BEGIN')
        elif operation == 'commit':
            cursor.execute('COMMIT')
        elif operation == 'rollback':
            cursor.execute('ROLLBACK')
    cursor.execute('INSERT INTO t DEFAULT VALUES')
    cursor.execute('SELECT id FROM t WHERE rowid = (SELECT MAX(rowid) FROM t)')
    result = cursor.fetchone()[0]
    connection.close()
    return int(result)
